-- Resources content for the query-core change (CLAUDE.md, "Resources stay in step with the code"). Content only; no schema. Follows
-- 20261126120000. The three guides are updated in place (a guide an editor has changed since is flagged for review and not overwritten)
-- and one release note says what changed: the campaign is gone and every query can be convened around.
--
-- Station-neutral on purpose: a guide is kept data, and the fresh-install check fails on any kept guide that names a station.

select private.rc_release_guide(
  p_slug => 'audience-listening-campaigns-events-and-table-cards',
  p_tool_key => 'audience-listening',
  p_title => 'Events, hosting and table cards',
  p_summary => 'Convene people around a query, choose who may host, get a public event listed, and print the cards for its tables.',
  p_screen_keys => array['audience-listening.events', 'audience-listening.event'],
  p_sort_order => 50,
  p_version_note => 'Campaigns are gone: events belong to a query, and a query says who may host',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every query can be convened around. A query on its own is a reporter's questions answered alone; with "},{"type":"text","text":"events","marks":[{"type":"bold"}]},{"type":"text","text":" it is also a conversation people have together, in a small group or a large one. An event is a session in a place at a time, and a "},{"type":"text","text":"table","marks":[{"type":"bold"}]},{"type":"text","text":" is one conversation at it. A kitchen table is an event with one table. The same questions are asked either way: what a person answers alone is what a table discusses."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Events on a query"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a query and choose its "},{"type":"text","text":"Events","marks":[{"type":"bold"}]},{"type":"text","text":" tab, then "},{"type":"text","text":"New event","marks":[{"type":"bold"}]},{"type":"text","text":". Give it a title, a start and end, a place, and whether it is private or public. It starts as a draft and nothing is public."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The start has to fall inside the query's dates, if it has any; the Portal refuses it otherwise. Times are the station's local time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Planned length","marks":[{"type":"bold"}]},{"type":"text","text":" is how long the session is meant to run. It sets the time suggested for each question, shared equally after the opening and the last five minutes. Leave it blank to use the time from start to end. It is only a suggestion; tables move on at their own pace."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Events","marks":[{"type":"bold"}]},{"type":"text","text":" item in the navigation lists every query's events, soonest first."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Who may host"}]},{"type":"paragraph","content":[{"type":"text","text":"Under the query's "},{"type":"text","text":"Settings","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Hosting","marks":[{"type":"bold"}]},{"type":"text","text":" says who besides staff may convene around it."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Staff only","marks":[{"type":"bold"}]},{"type":"text","text":": only staff make events. The query's page does not invite anyone to host."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Anyone may start a private table","marks":[{"type":"bold"}]},{"type":"text","text":": the website offers \"Host a table of your own\". A person starts one private table on their own phone and chooses how long it will run (30, 45 or 60 minutes). It appears under Events as a private event with one table, named for the query. Nothing about it is public, and each person can start three a day."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Anyone may start a private table or ask to host a session","marks":[{"type":"bold"}]},{"type":"text","text":": also adds \"Bring a session to your table\", a request that staff read under Host requests and schedule. Every request is about a query; there is no general request."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The person who made the query is who the hourly run acts as when it sends recordings to Sourcework, so they need access to Sourcework. If they lose it, recordings wait for a person to send them by hand."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Public events"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A private event is never listed. The organizer shares it themselves."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A listed public event that is still to come appears on the website's listening page beside its query, with its seats left. It leaves that list once it has ended or been taken off the website."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A public event needs an address and a number of seats, and can be listed only after a coordinator approves it. Anyone can ask for a review. A coordinator approves it after ticking each item on the checklist (a public place, an identified organizer with a verified email, a date inside the query's window, accessibility details, not a fundraiser or campaign event, and the consent reading acknowledged), or declines it with a reason the organizer is told."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If anyone other than a coordinator changes what the public sees on a listed event (its title, time, place, address or seats), it goes back to review. Making an event private takes it off the website at once."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Approving, declining and taking an event off the website are recorded with who did them. The Events page can show only those waiting for review, and the count appears beside Events in the navigation."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tables and cards"}]},{"type":"paragraph","content":[{"type":"text","text":"On an event, add the tables it needs. Make new links and cards for every table gives each table a single-use link and draws a card for it with a QR code, to print at 7 by 5 inches, one to a page."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A link is shown once, on that page. The Portal keeps only a scrambled copy, so a card cannot be reprinted later. To get a card back, make a new link."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A new link replaces the old one. A card printed earlier, and any phone using it, stops working. If one phone is lost or cannot scan, make a new link for that table alone and read it out or show it to the person."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The card also carries a second QR code, for leaving a contact card. It is made together with the links when you make them for every table, and not when you replace one table's link, so a new link in the middle of a night does not break the card people are already using."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Making links needs the website's address, which an administrator sets under Administration > Station. If it is not set, the page says so instead of printing a card that goes nowhere."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Opening a card's link does not use it up; the table's phone does that when its facilitator presses the button. A card that was only scanned to see where it goes still works."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A table that has not started can be removed. One that has been agreed to or recorded is kept."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Seats"}]},{"type":"paragraph","content":[{"type":"text","text":"A public event shows the seats people have saved, each with a name and an email given for that event only. Remove one to free the seat and delete the details."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The organizer's room"}]},{"type":"paragraph","content":[{"type":"text","text":"A person running an event can follow where every table is from the website, move the room on to the next question, call the last five minutes and clear a table's request for a hand. They never see what anyone says. They need an account on the website, and a link from you."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A coordinator chooses Make an organizer link on the event. The link is shown once, and the Portal keeps only a scrambled copy. Give it to the person running the event."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Whoever opens it signed in to the website and presses the button becomes the organizer, so give it to one person. Making a new link lets a different account take over."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An event with no organizer account is run from Tonight in the Portal."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Before the first real session, make links, print one card and run one table on a real phone for a few minutes, so you know that phone records and sends. That test uses the table's link up, so make a new link for the table before the real night. Tell facilitators to plug the phone in and keep the page open: the page says so too."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nothing on these pages is public until you say so, and a public event is never listed without a coordinator."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'audience-listening-consent-wording-and-tables',
  p_tool_key => 'audience-listening',
  p_title => 'Consent and opening wording, and what happens at a table',
  p_summary => 'Write the words a facilitator reads aloud and the opening every recording starts with, and see how a table agrees, records and finishes.',
  p_screen_keys => array['audience-listening.consent'],
  p_sort_order => 60,
  p_version_note => 'The opening of every recording, kept beside the consent wording',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two pieces of wording are the same for every table of every query, and both are kept here: what the facilitator reads aloud before a table records, and what each person says at the very start of the recording. Open them from "},{"type":"text","text":"Wording","marks":[{"type":"bold"}]},{"type":"text","text":" in the section's navigation."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The consent wording"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The words are kept as numbered versions. A version is never edited: a change is a new version, so each table's agreement points at the exact words its facilitator read."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only a coordinator can add a version. Settle the wording with the University's counsel and the records officer before the first real session."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"With no wording saved, no table can open, because its page would have nothing to read aloud. The event page says so."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The opening of every recording"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It is what each person says first, on the recording itself, so every voice agrees on the tape: for example a first name, where they live, and that they are okay being recorded. The consent wording is read to the table; this is said by each person."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It is shown on the table's phone after the agreement and before the first question. It is the same for every query, and a reporter cannot change it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Like the consent wording it is kept as numbered versions that are never edited, only a coordinator adds one, and each table records which version it was shown. With none saved, tables start straight into the questions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Someone answering a query alone is not asked to say it; their agreement is the box they tick before sending."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What happens at a table"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The card's QR code opens the table's single-use link. Opening it starts a session for that phone. A second phone using the same link is turned away."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The facilitator reads the wording and taps to agree. The Portal records when, the wording version and the opening version they were shown, their first name if they gave one, their email, which they must give so the Portal can send them one link afterwards, and how many are at the table if they said, which only helps the transcript tell the voices apart. Nothing records before this."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The phone records in segments of at most five minutes and uploads each as it goes, so a dropped connection picks up where it left off. It asks the screen to stay awake, takes that back if the page was hidden, and says so on the screen if the microphone stops, a call mutes it or the phone locks: a banner, and a button to reconnect the microphone. Each segment carries the time the phone started it, so the Table page can show where nothing was recorded. When the table ends, the conversation is complete once every segment has arrived."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the event page each table shows when it agreed, to which version, who facilitated, whether it asked for a hand, and how much has been recorded. If a phone is lost, make a new link for that table: it ends the old session."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Try one table on a real phone before the first real session."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"After a table, see \"Tonight, tables after the session and purging\" for sending a recording to Sourcework, the facilitator's after-page and contact cards."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'audience-listening-tonight-tables-and-purging',
  p_tool_key => 'audience-listening',
  p_title => 'Tonight, tables after the session and purging',
  p_summary => 'Run an event, send a recording to Sourcework, review what the facilitator marked and the contact cards, and purge what is due.',
  p_screen_keys => array['audience-listening.tonight', 'audience-listening.table', 'audience-listening.purge', 'audience-listening.jobs'],
  p_sort_order => 70,
  p_version_note => 'Suggested time for each question, marks with a note instead of a tag, and the query as the owner of the hand-off',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Three screens cover the session itself and what follows it: "},{"type":"text","text":"Tonight","marks":[{"type":"bold"}]},{"type":"text","text":" while an event runs, the "},{"type":"text","text":"Table","marks":[{"type":"bold"}]},{"type":"text","text":" page after it, and "},{"type":"text","text":"Purge","marks":[{"type":"bold"}]},{"type":"text","text":" for retention."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tonight"}]},{"type":"paragraph","content":[{"type":"text","text":"Open Tonight from an event. Keep it open for the session."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It checks in every 15 seconds. Tables are told that help is coming only while a screen like this is open; otherwise their phone says the request is flagged and, if it is urgent, to ask at the front."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Turn sound on so a new request for a hand makes a tone as well as a notice. Browsers only allow sound after you click, so it starts off."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A table that asks for a hand shows a badge. Choose \"Someone is on the way\" once it is dealt with."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The room card says how long the session is planned for and about how long each question gets. It is a suggestion: tables move on at their own pace."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Move the room to a question, or call the last five minutes, which tables then see. A last call is made once."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The After list shows where each table's recording has got to. The hourly run sends finished recordings on and emails facilitators, but a table still marked Recording or Uploading the next day needs a look: its phone may have lost the page. Open the table to see how much arrived."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"After a table"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a table from its event. It shows when the table agreed, to which wording version, and how much was recorded."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Once the table has ended and every segment has uploaded, the hourly run sends the recording to Sourcework as the query's owner, and Send to Sourcework does the same at once. It needs access to Sourcework. The segments are joined into one recording and the transcript starts, told roughly how many people were at the table and listening for people saying their own names. The first table sent makes the query's Sourcework project; later tables become sources in it. The original segments are kept. The Table page says where the phone recorded nothing for twenty seconds or more: a pause the table chose, or a phone that locked."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Recorded on a separate recorder? On a table that has agreed, attach the file on its Table page (MP3, M4A, WAV, WebM or Ogg, up to 50 MB; export long recordings as a mono MP3 at 64 kbps). It reads like any other table afterwards. It cannot be replaced once attached, and a table that never agreed cannot be given one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"When the transcript is ready, the facilitator's after-page shows only that table's lines. Where the transcript heard someone say their name, it offers it as a name to confirm with one press, and it lists lines that may matter for the facilitator to mark or set aside. Nothing is named or marked until they press. They name the voices by first name, mark the lines that mattered, and send the conversation. Naming is optional."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A mark can carry a note: a few words from the facilitator on why the line mattered. There is no list of tags to choose from. Sourcework finds the themes afterwards, from everything that was said, so nothing is decided before anyone has listened. The Table page shows the transcript with the names, marks and notes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Excerpts from the marked lines. Each marked line becomes a Sourcework excerpt, once, with the note as its reason. The hourly run does it when the transcript is ready; Make excerpts from the marked lines on the Table page does it at once, in your name."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Email the facilitator their link. The Table page shows the email they gave. The hourly run emails each facilitator their link once their table's transcript is ready, and Email the link to the facilitator sends it sooner or again. A button under the tables on the event page reaches every table that has an email, a recording not yet sent and no link yet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The link opens that table's page only, works for fourteen days and cannot record. A new link replaces the last, so sending again is how to recover from one that went astray. If the email cannot be sent (the server's email is not set up, for one) the page shows the link so you can hand it over yourself."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A line that was marked keeps the words it had when it was marked, even if the recording is transcribed again."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Contact cards"}]},{"type":"paragraph","content":[{"type":"text","text":"People at a table can scan the card's second QR code and leave a first name, a way to reach them, and three separate choices: may be contacted, may be named, keep anonymous. Naming and anonymous cannot both be chosen. All three start off."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Table page is the only place a card's contents appear. The facilitator sees how many were left, never what they say."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A person can say you may contact them and leave no way to reach them. The card is kept as they chose it and you are told."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mark a card as contacted once you have. Approving the use of a name is refused until you have, and for anyone who did not say they could be named."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deleting a card removes everything on it for good."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Purge"}]},{"type":"paragraph","content":[{"type":"text","text":"Purge lists what is due and lets a coordinator delete it. Nothing is purged on its own."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An unfinished submission, with its answers and audio, is due after 30 days untouched."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A conversation the facilitator never sent is due 30 days after its event ended, with its segments, voices, marks and contact cards. One that holds a card someone has already acted on, by contacting the person or approving their name, is kept, because that card is the record of what they agreed to. The Purge screen says how many are kept."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A facilitator's email and after-page link are cleared on their own, 30 days after the event, whether or not the conversation was sent. A conversation is never deleted on a schedule: the weekly reminder says when something is due and a coordinator presses the button."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A conversation the facilitator sent is never purged here. Contact cards and unused raw audio follow the query's report date, which is not set up yet, so neither is due."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Scheduled work"}]},{"type":"paragraph","content":[{"type":"text","text":"Once an hour the Portal does the small jobs nobody should have to remember. Scheduled work in the section's navigation lists each task of each run and what it did, so you can see it working. It does six things:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"sends finished recordings to Sourcework, two a run, as the query's owner;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"emails facilitators their link when their table's transcript is ready;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"makes Sourcework excerpts from marked lines;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"clears facilitators' emails and links 30 days after the event;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"emails the shared mailbox a reminder once a week when recordings are past their thirty days;"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"emails the shared mailbox once a day when questions or requests are waiting."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A task that cannot do its work (the owner has lost access to Sourcework, the website address or the mailbox is not set, the email is not set up) says so on that page and leaves the work for a person; the other tasks still run. If the page says nothing has run, the server's schedule secret is not set or the hosting plan does not allow an hourly schedule."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An event's organizer runs the room from the website, once a coordinator has given them a link from the event page. It shows where each table is, moves the room on and calls the last five minutes, and never shows what was said."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If an Audience Listening mailbox is set under Administration > Station, an email goes to it when someone asks to host a session, a short one each day anything is waiting in Questions and ideas or Host requests (counts only, and which requests have waited past five days), and one a week when recordings are past their thirty days. None carries anything a person wrote."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-11-27-audience-listening-query-core',
  p_tool_key => 'audience-listening',
  p_released_on => '2026-11-27',
  p_title => 'Every query can be convened around',
  p_guide_slugs => array['audience-listening-campaigns-events-and-table-cards', 'audience-listening-consent-wording-and-tables', 'audience-listening-tonight-tables-and-purging'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The query is now the one thing a reporter makes, and every query can be convened around. The separate campaign is gone: its question, dates, owner and Sourcework project are the query's own, and a query's Events tab holds the sessions people hold around it, in a small group or a large one. A table discusses the same questions an individual answers alone, with no second list of prompts."}]},{"type":"paragraph","content":[{"type":"text","text":"A query's Settings say who may host: staff only, anyone starting a private table, or anyone also asking to host a session. Every request to host is about a query. A kitchen table's host chooses how long it will run, and each event can say how long it is planned for, which sets about how long each question gets, shown on Tonight and on the table's phone."}]},{"type":"paragraph","content":[{"type":"text","text":"What every recording opens with, each person saying their first name, where they live and that they agree, is now kept once for the whole station as numbered versions, next to the consent wording on the new Wording page. Each table records which version it was shown."}]},{"type":"paragraph","content":[{"type":"text","text":"The list of tags is gone, because themes are for Sourcework to find. A facilitator still marks the lines that mattered, and can add a few words on why."}]}]}$body$
);
